class Solution:
    def findWords(self, board: list[list[str]], words: list[str]) -> list[str]:
        m, n = len(board), len(board[0])

        def dfs(r, c, word, idx):
            if idx == len(word):
                return True
            if r < 0 or r >= m or c < 0 or c >= n or board[r][c] != word[idx]:
                return False
            tmp = board[r][c]
            board[r][c] = '#'
            found = (dfs(r + 1, c, word, idx + 1) or dfs(r - 1, c, word, idx + 1)
                     or dfs(r, c + 1, word, idx + 1) or dfs(r, c - 1, word, idx + 1))
            board[r][c] = tmp
            return found

        result = []
        for word in words:
            if any(dfs(r, c, word, 0) for r in range(m) for c in range(n)):
                result.append(word)
        return result

